import * as THREE from 'three';
import {pulse} from './preferences.js';
import {GLTFLoader} from './assets/GLTFLoader.js';
const loader=new GLTFLoader(),cache=new Map(),views=new Set(),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let pointer={x:0,y:0},scroll=0;
addEventListener('pointermove',e=>{pointer.x=e.clientX/innerWidth-.5;pointer.y=e.clientY/innerHeight-.5},{passive:true});
addEventListener('scroll',()=>scroll=window.scrollY,{passive:true});
function load(name){if(!cache.has(name))cache.set(name,loader.loadAsync('/assets/sculptures/'+name+'.glb'));return cache.get(name)}
function oriented(source){const wrapper=new THREE.Group(),model=source.clone(true);model.rotation.x+=Math.PI/2;wrapper.add(model);wrapper.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(wrapper);wrapper.position.sub(box.getCenter(new THREE.Vector3()));const root=new THREE.Group();root.add(wrapper);return root}
function grain(material){material.onBeforeCompile=shader=>{shader.fragmentShader=shader.fragmentShader.replace('#include <dithering_fragment>','#include <dithering_fragment>\nfloat grain = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898,78.233))) * 43758.5453);\ngl_FragColor.rgb *= 0.975 + grain * 0.05;')};return material}
function solarSurface(material){const base=material.onBeforeCompile;material.onBeforeCompile=shader=>{base(shader);shader.vertexShader='varying vec3 vSolarPosition;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nvSolarPosition = position;');shader.fragmentShader='varying vec3 vSolarPosition;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\nfloat swirls = sin(vSolarPosition.x*9.0 + sin(vSolarPosition.y*12.0) + vSolarPosition.z*7.0)*sin(vSolarPosition.z*13.0 + vSolarPosition.y*5.0);\nfloat detail = sin(vSolarPosition.x*73.0)*sin(vSolarPosition.y*67.0)*sin(vSolarPosition.z*71.0);\ndiffuseColor.rgb *= .91 + swirls*.10 + detail*.025;')};material.customProgramCacheKey=()=> 'solar-surface-v1'}
class LiveView{
 constructor(host){this.host=host;this.canvas=document.createElement('canvas');this.canvas.className='live-canvas';this.canvas.setAttribute('role','img');this.canvas.tabIndex=0;this.canvas.setAttribute('aria-description','Drag left or right to rotate horizontally. Tap or press Enter to spin. Left and right arrows rotate. R resets the view.');host.replaceChildren(this.canvas);this.renderer=new THREE.WebGLRenderer({canvas:this.canvas,alpha:true,antialias:true,powerPreference:'low-power'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));this.renderer.setClearColor(0xffffff,0);this.renderer.outputColorSpace=THREE.SRGBColorSpace;this.renderer.toneMapping=THREE.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.15;this.scene=new THREE.Scene();this.camera=new THREE.OrthographicCamera(-2,2,2,-2,.1,40);this.camera.position.set(0,0,10);this.scene.add(new THREE.HemisphereLight(0xffffff,0x323238,2));const key=new THREE.DirectionalLight(0xffffff,3);key.position.set(-3,4,6);this.scene.add(key);const edge=new THREE.DirectionalLight(0xffffff,2);edge.position.set(4,1,2);this.scene.add(edge);this.red=new THREE.SpotLight(0xff122b,28,15,.38,.7,1);this.red.position.set(0,3.6,2);this.red.target.position.set(0,1.4,0);this.scene.add(this.red,this.red.target);this.content=new THREE.Group();this.scene.add(this.content);this.key='';this.ticket=0;this.active=true;this.parts=[];this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(host);this.visibleObserver=new IntersectionObserver(entries=>{this.active=entries[0].isIntersecting},{rootMargin:'100px'});this.visibleObserver.observe(host);this.rotation={yaw:0,pitch:0,x:0,y:0};this.drag=null;this.velocity=0;this.bindInteraction();this.theme();addEventListener('atmos-theme',()=>this.theme());views.add(this);this.resize()}
 theme(){const name=document.documentElement.dataset.theme;this.dark=name==='dark'||name==='red';this.renderer.toneMappingExposure=this.dark?1.55:1.15;const accents={light:0xff122b,dark:0xff4564,yellow:0xff7715,red:0xffa293,grey:0xa7bbd0};this.red.color.setHex(accents[name]??accents.light);this.content.traverse(o=>{if(o.isMesh&&o.material){if(!o.userData.lightColor)o.userData.lightColor=o.material.color.clone();o.material.color.copy(o.userData.lightColor);if(this.dark&&(this.kind==='digits'||this.value==='air'||this.value==='precip'))o.material.color.lerp(new THREE.Color(0x65707d),.48);if(this.value==='sun')o.material.color.setHex(accents[name]??accents.light)}})}

 bindInteraction(){const canvas=this.canvas,spin=()=>{this.rotation.yaw+=reduced?Math.PI/4:Math.PI*2;this.velocity=0;pulse(14)};canvas.addEventListener('pointerdown',e=>{if(e.isPrimary===false||e.button>0)return;this.drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};this.velocity=0;canvas.setPointerCapture(e.pointerId);canvas.classList.add('dragging');pulse(7)});canvas.addEventListener('pointermove',e=>{if(!this.drag||this.drag.id!==e.pointerId)return;const dx=e.clientX-this.drag.x,dy=e.clientY-this.drag.y;if(Math.hypot(e.clientX-this.drag.startX,e.clientY-this.drag.startY)>6)this.drag.moved=true;if(this.drag.moved){this.rotation.yaw+=dx*.012;this.velocity=THREE.MathUtils.clamp(dx*.008,-.12,.12)}this.drag.x=e.clientX;this.drag.y=e.clientY});const end=(e,cancel=false)=>{if(!this.drag||this.drag.id!==e.pointerId)return;const tapped=!this.drag.moved;this.drag=null;canvas.classList.remove('dragging');if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(cancel)this.velocity=0;else if(tapped)spin();else pulse(6)};canvas.addEventListener('pointerup',e=>end(e));canvas.addEventListener('pointercancel',e=>end(e,true));canvas.addEventListener('lostpointercapture',()=>{this.drag=null;canvas.classList.remove('dragging')});canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Enter',' ','r','R'].includes(e.key))return;e.preventDefault();if(e.key==='Enter'||e.key===' ')spin();else if(e.key.toLowerCase()==='r'){this.rotation.yaw=0;this.rotation.pitch=0;this.velocity=0;pulse()}else{this.rotation.yaw+=(e.key==='ArrowRight'?.25:e.key==='ArrowLeft'?-.25:0);pulse()}})}
 resize(){const r=this.host.getBoundingClientRect();if(!r.width||!r.height)return;const height=this.kind==='digits'?3.35:3.65,aspect=r.width/r.height;this.camera.left=-height*aspect/2;this.camera.right=height*aspect/2;this.camera.top=height/2;this.camera.bottom=-height/2;this.camera.updateProjectionMatrix();this.renderer.setSize(r.width,r.height,false)}
 async show(kind,value){const key=kind+':'+value;if(this.key===key)return;if(this.kind!==kind||(kind==='weather'&&this.value!==value)){this.rotation.yaw=0;this.rotation.y=0;this.velocity=0}this.key=key;this.kind=kind;this.value=value;const ticket=++this.ticket;this.canvas.setAttribute('aria-label',kind==='digits'?value+' degrees, live 3D temperature':'Live 3D '+value);this.red.visible=kind==='digits';this.resize();try{const names=kind==='digits'?String(value).split('').map(c=>'digit-'+(c==='-'?'minus':c)):[value];if(names.some(n=>n.includes('—')))return;const models=await Promise.all(names.map(load));if(ticket!==this.ticket)return;this.clear();this.parts=[];let cursor=0;const group=new THREE.Group();models.forEach((g,j)=>{const obj=oriented(g.scene);obj.traverse(m=>{if(!m.isMesh)return;m.material=grain(m.material.clone());if(kind==='digits'){m.material.color.setHex(0x151515);m.material.roughness=.48;m.material.metalness=.18}if(value==='sun'){solarSurface(m.material);m.material.color.setHex(0xff0629);m.material.roughness=.77;m.material.metalness=0}if(value==='moon'){m.material.roughness=1;m.material.metalness=0}m.userData.origin=m.position.clone();if(value==='precip'&&m.name.startsWith('Cylinder'))this.parts.push(m);if(value==='air'&&m.name.startsWith('Anemometer'))this.parts.push(m)});if(kind==='digits'){const box=new THREE.Box3().setFromObject(obj),width=box.max.x-box.min.x;obj.position.x=cursor+width/2;cursor+=width+.10;}group.add(obj)});if(kind==='digits')group.position.x=-(cursor-.10)/2;this.content.add(group);this.theme();this.born=performance.now();this.host.classList.remove('live-error');}catch(e){this.host.classList.add('live-error');this.canvas.setAttribute('aria-label','3D model unavailable');if(!this.host.querySelector('.scene-error')){const p=document.createElement('p');p.className='scene-error';p.textContent='3D view could not load. Refresh to retry.';this.host.append(p)}}}
 clear(){this.content.traverse(o=>{if(o.isMesh)o.material.dispose()});this.content.clear()}
 render(t){if(!this.active||!this.host.isConnected)return;const s=t*.001;if(!reduced){const entrance=Math.min(1,(t-(this.born||0))/450);const ease=1-Math.pow(1-entrance,3);this.content.position.y=(1-ease)*-.3+Math.sin(s*.85)*(this.kind==='digits'?.025:.07);this.content.scale.setScalar(.93+.07*ease);this.content.rotation.y=pointer.x*.2+Math.sin(s*.36)*.045+Math.min(scroll*.00015,.12);this.content.rotation.x=0;this.content.rotation.z=0;if(this.value==='air')this.content.rotation.y=Math.sin(s*.55)*.34+pointer.x*.15;if(this.value==='moon')this.content.rotation.y=0;this.parts.forEach((p,i)=>{if(this.value==='precip'){p.position.z=p.userData.origin.z+((s*1.6+i*.13)%1.5)-.7}else{p.rotation.y=s*2.1+i*2.09}})}if(!this.drag&&!reduced){this.rotation.yaw+=this.velocity;this.velocity*=.92}const blend=reduced?1:.18;this.rotation.y+=(this.rotation.yaw-this.rotation.y)*blend;this.content.rotation.x=0;this.content.rotation.z=0;this.content.rotation.y=(reduced?0:this.content.rotation.y)+this.rotation.y;this.renderer.render(this.scene,this.camera)}
}
const instances=new WeakMap();
export function mountLive(host,kind,value){try{let v=instances.get(host);if(!v){v=new LiveView(host);instances.set(host,v)}v.show(kind,value);return true}catch{host.textContent=kind==='digits'?String(value):'3D is unavailable in this browser.';return false}}
let last=0;function frame(t){requestAnimationFrame(frame);if(document.hidden||t-last<33)return;last=t;views.forEach(v=>v.render(t))}requestAnimationFrame(frame);
